  1428  /// Converts a BAM aux tag to SAM format
  1429  /*
  1430   * @param b    Pointer to the bam record
  1431   * @param key  Two letter tag key
  1432   * @param type Single letter type code: ACcSsIifHZB.
  1433   * @param tag  Tag data pointer, in BAM format
  1434   * @param end  Pointer to end of bam record (largest extent of tag)
  1435   * @param ks   Kstring to write the formatted tag to
  1436   *
  1437   * @return pointer to end of tag on success,
  1438   *         NULL on failure.
  1439   *
  1440   * @discussion The three separate parameters key, type, tag may be
  1441   * derived from a s=bam_aux_get() query as s-2, *s and s+1.  However
  1442   * it is recommended to use bam_aux_get_str in this situation.
  1443   * The desire to split these parameters up is for potential processing
  1444   * of non-BAM formats that encode using a BAM type mechanism
  1445   * (such as the internal CRAM representation).
  1446   */
  1447  static inline const uint8_t *sam_format_aux1(const uint8_t *key,
  1448                                               const uint8_t type,
  1449                                               const uint8_t *tag,
  1450                                               const uint8_t *end,
  1451                                               kstring_t *ks) {
  1452      int r = 0;
  1453      const uint8_t *s = tag; // brevity and consistency with other code.
  1454      r |= kputsn_((char*)key, 2, ks) < 0;
  1455      r |= kputc_(':', ks) < 0;
  1456      if (type == 'C') {
  1457          r |= kputsn_("i:", 2, ks) < 0;
  1458          r |= kputw(*s, ks) < 0;
  1459          ++s;
  1460      } else if (type == 'c') {
  1461          r |= kputsn_("i:", 2, ks) < 0;
  1462          r |= kputw(*(int8_t*)s, ks) < 0;
  1463          ++s;
  1464      } else if (type == 'S') {
  1465          if (end - s >= 2) {
  1466              r |= kputsn_("i:", 2, ks) < 0;
  1467              r |= kputuw(le_to_u16(s), ks) < 0;
  1468              s += 2;
  1469          } else goto bad_aux;
  1470      } else if (type == 's') {
  1471          if (end - s >= 2) {
  1472              r |= kputsn_("i:", 2, ks) < 0;
  1473              r |= kputw(le_to_i16(s), ks) < 0;
  1474              s += 2;
  1475          } else goto bad_aux;
  1476      } else if (type == 'I') {
  1477          if (end - s >= 4) {
  1478              r |= kputsn_("i:", 2, ks) < 0;
  1479              r |= kputuw(le_to_u32(s), ks) < 0;
  1480              s += 4;
  1481          } else goto bad_aux;
  1482      } else if (type == 'i') {
  1483          if (end - s >= 4) {
  1484              r |= kputsn_("i:", 2, ks) < 0;
  1485              r |= kputw(le_to_i32(s), ks) < 0;
  1486              s += 4;
  1487          } else goto bad_aux;
  1488      } else if (type == 'A') {
  1489          r |= kputsn_("A:", 2, ks) < 0;
  1490          r |= kputc_(*s, ks) < 0;
  1491          ++s;
  1492      } else if (type == 'f') {
  1493          if (end - s >= 4) {
  1494              ksprintf(ks, "f:%g", le_to_float(s));
  1495              s += 4;
  1496          } else goto bad_aux;
  1497
  1498      } else if (type == 'd') {
  1499          // NB: "d" is not an official type in the SAM spec.
  1500          // However for unknown reasons samtools has always supported this.
  1501          // We believe, HOPE, it is not in general usage and we do not
  1502          // encourage it.
  1503          if (end - s >= 8) {
  1504              ksprintf(ks, "d:%g", le_to_double(s));
  1505              s += 8;
  1506          } else goto bad_aux;
  1507      } else if (type == 'Z' || type == 'H') {
