  1630  /// Return a SAM formatting string containing a BAM tag
  1631  /** @param b   Pointer to the bam record
  1632      @param tag Desired aux tag
  1633      @param s   The kstring to write to.
  1634
  1635      @return 1 on success,
  1636              0 on no tag found with errno = ENOENT,
  1637             -1 on error (errno will be either EINVAL or ENOMEM).
  1638   */
  1639  static inline int bam_aux_get_str(const bam1_t *b,
  1640                                    const char tag[2],
  1641                                    kstring_t *s) {
  1642      const uint8_t *t = bam_aux_get(b, tag);
  1643      if (!t)
  1644          return errno == ENOENT ? 0 : -1;
  1645
  1646      if (!sam_format_aux1(t-2, *t, t+1, b->data + b->l_data, s))
  1647          return -1;
  1648
  1649      return 1;
  1650  }
